// ---------------------------------------------------------------------------
@Component
@RequiredArgsConstructor
class P050StartupRunner implements ApplicationRunner {

    private final SaldosTesoreriaClient l006;     // antes: SALDOS IN LIB-L006

    @Override
    public void run(ApplicationArguments args) {
        // DAME_TIT IN CTLVERS deja de existir: el endpoint de L006 llega por configuración
        // y Spring falla al arrancar si no está definido, en lugar de usar un título fijo.
        int resultado = l006.saldos(SaldosRequest.funcion(10));   // FUNCION 10 = inicializa contexto
        if (resultado != 0) {
            // El fuente guarda el resultado en WKS-151-RESULT y no lo revisa.
            log.warn("SALDOS IN LIB-L006 FUNCION 10 devolvió {}", resultado);
        }
    }
}

# application.yml  (antes: literales en 100-PRINCIPIA)
p050:
  nodo:
    csi-envio-override: { "10": 4, "32": 12 }   # 77-CSI-ENV
    id-titulo: { "10": 1, default: 2 }          # WKS-TIT-IDCSI
    corrige-feccon-csi: [4, 10]

// ---------------------------------------------------------------------------
@ConfigurationProperties("p050.nodo")
record NodoProperties(Map<String, Integer> csiEnvioOverride,
                      Map<String, Integer> idTitulo,
                      Set<Integer> corrigeFecconCsi) {

    int csiEnvio(int csi) { return csiEnvioOverride.getOrDefault(String.valueOf(csi), csi); }
}

@Service
@RequiredArgsConstructor
class ContextoNodoService {

    private final NodoProperties props;
    private final ControlS151Client control;   // CONSISDIA IN S151LIBCONTROL

    ContextoNodo resuelve(int csi, LocalDate fechaMaquina) {
        SistemaDia sis500 = control.consisdia(csi, 500, 1)
                .orElseThrow(() -> new ArranqueFallidoException(
                        "ERROR AL CONSULTAR S151LIBCONTROL PARA OBTENER NOMBRE DE LA BASE DIARIA"));

        // IF WKS-NUMCSI = 4 OR 10 AND FECCON < MAQUINA se evalúa como
        // (CSI = 4) OR (CSI = 10 AND FECCON < MAQUINA): AND precede a OR.
        LocalDate feccon = sis500.fecCon();
        if (csi == 4 || (csi == 10 && feccon.isBefore(fechaMaquina))) {
            feccon = fechaMaquina;
        }
        return new ContextoNodo(csi, props.csiEnvio(csi),
                sis500.nombreBaseSemanal(), sis500.packMovimientos(),
                feccon,            // WKS-LOG1-FECHA y WKS-S500-FECHA
                fechaMaquina);     // W77-FCH-S500: el fuente la sobrescribe con la fecha máquina
    }
}

@Service
@RequiredArgsConstructor
class FechaProcesoService {

    private final CalendarioBancario calendario;   // reemplaza THECALENDAR IN LOCSUP

    /**
     * FUN 18 devuelve 1 si la fecha es hábil y 0 si no lo es
     * (88 DIA-HABIL VALUE 1). Con 0 se pide el siguiente hábil (FUN 13, +1).
     */
    LocalDate fechaProcesoHabil(LocalDate hoy) {
        return calendario.esHabil(hoy)
                ? hoy
                : calendario.sumaDiasHabiles(hoy, 1);
    }
}

@Service
@RequiredArgsConstructor
class ControlAdSaldoService {

    private final ControlAdSaldoRepository control;   // S151BD02ADSALDO, registro B92-CTR
    private final P050Properties props;

    /** LOCK + BEGIN-TRANSACTION + STORE + END-TRANSACTION AUDIT. */
    @Transactional
    ControlAdSaldo marcaInicio(LocalDate fechaProceso) {
        ControlAdSaldo ctr = control.findForUpdate()                    // LOCK S151BD02ADSALDO
                .orElseThrow(() -> new ArranqueFallidoException("900-TRUENE"));
        // "M" solo para CSI 4; cualquier otro CSI se marca como "V"
        char nodoTcp = props.nodo().csiMonterrey() == ctr.getCsi() ? 'M' : 'V';
        ctr.setFecha(fechaProceso);                                     // B92-CTR-FECHA
        return ctr.withNodoTcp(nodoTcp);                                // STORE en el commit
    }
}

@Component
@RequiredArgsConstructor
class VentanaEnvioScheduler {

    private final FechaProcesoService fechas;
    private final CalendarioBancario calendario;
    private final Clock clock;
    private volatile boolean diaHabil;        // WS-DIA-HABIL / 88 DIA-HABIL

    /** Antes corría en cada vuelta de ESPERACOMS (timeout de 60 s). */
    @Scheduled(fixedDelayString = "${p050.ciclo.espera:PT60S}")
    void refrescaCalendario() {
        LocalDate hoy = LocalDate.now(clock);   // la fecha se toma siempre, sin la condición
        diaHabil = calendario.esHabil(hoy);     // FUN 18
    }
}

/** Cada PERFORM del IF anidado se vuelve una implementación registrada por código. */
public interface FuncionSaldos {
    int codigo();
    void atiende(MensajeComs msg, Respuesta resp);
}

@Service
@RequiredArgsConstructor
class AdSaldoMessageHandler {

    private static final Set<Integer> SIN_ACCION = Set.of(25, 72, 73);   // NEXT SENTENCE en el fuente
    private final List<FuncionSaldos> funciones;   // 300-GLOBALES, 400-SUCURSAL, ... 22000-BUSCA-MOVS
    private final LogSaldosWriter logSaldos;       // 245-GRABA-LOGSALDOS
    private final ConcentracionTotales concentra;  // 205-VERIFICA-SAR + 210-VERIFICA-DIALOGO
    private Map<Integer, FuncionSaldos> porCodigo;

    @PostConstruct
    void indexa() {
        porCodigo = funciones.stream()
                .collect(Collectors.toUnmodifiableMap(FuncionSaldos::codigo, f -> f));
    }

    Respuesta maneja(MensajeComs msg) {
        if (msg.hdrRes() == 2) logSaldos.graba(msg);
        var resp = Respuesta.nueva();                  // WS-ERROR = 0, WS-FORMATOS = SPACES
        int fun = msg.funcion();                       // WS-TXT-FUN
        if (fun == 1 && msg.hdrRes() == 2) {
            concentra.verificaSarYDialogo();           // función 1 como respuesta: concentra
        } else if (!SIN_ACCION.contains(fun)) {
            Optional.ofNullable(porCodigo.get(fun))
                    .ifPresentOrElse(f -> f.atiende(msg, resp),
                                     () -> resp.error(1));   // MOVE 1 TO WS-ERROR
        }
        return resp;                                   // PERFORM 800-RESPONDE
    }
}

/** Antes: cadena de IF en 250-VALIDA-SISTEMA. Agregar un sistema ya no requiere recompilar P050 si se lee de catálogo. */
public enum SistemaFinanciero {
    CHEQUES(1, "SISTEMA DE CHEQUES"),
    CUENTA_MAESTRA(66, "SISTEMA DE CUENTA MAESTRA"),
    INVERSIONES(87, "SISTEMA DE INVERSIONES"),
    LINEAS(151, "SISTEMA LINEAS SERV/CREDITO"),
    TRANSFERENCIA_FONDOS(264, "SIST. TRANSFERENCIA DE FONDOS"),
    CARTERA(400, "SISTEMA DE CARTERA"),
    AHORROS(500, "SISTEMA DE AHORROS"),
    HIPOTECARIOS(600, "SISTEMA DE P. HIPOTECARIOS");

    private final int codigo;
    private final String descripcion;
    SistemaFinanciero(int codigo, String descripcion) { this.codigo = codigo; this.descripcion = descripcion; }

    /** Rango 1..999 válido aunque no esté en la lista: se describe como NO CALIFICADO. */
    static String describe(int codigo) {
        if (codigo < 1 || codigo > 999) throw new ErrorFuncion(4);   // MOVE 4 TO WS-ERROR
        return Arrays.stream(values()).filter(s -> s.codigo == codigo)
                .map(s -> s.descripcion).findFirst()
                .orElse("SISTEMA NO CALIFICADO");
    }
}

@Service
class SaldosGlobalesService {

    private static final int POSICIONES = 20;                       // B01-GLO-SISTEMA(1..20)
    private static final BigDecimal MIL = BigDecimal.valueOf(1000);  // p050.escala-mxn

    /** 330-ASIGNA-SISTEMA: si el sistema no está en las 20 posiciones, el fuente usa la 20. */
    static int posicion(SaldoGlobal g, int sistema) {
        for (int i = 1; i <= POSICIONES; i++) {
            if (g.sistema(i) > 0 && g.sistema(i) == sistema) return i;
        }
        return POSICIONES;   // comportamiento del fuente, ver riesgo
    }

    /** 340-RESTO-CAMPOS: WS-VARIACION es PIC S9(10) y el COMPUTE no lleva ROUNDED. */
    static RenglonGlobal resto(SaldoGlobal g, int i, int moneda) {
        BigDecimal actual = escala(g.actual(i), moneda);
        BigDecimal antes  = escala(g.antes(i), moneda);
        BigDecimal varia  = escala(g.actual(i).subtract(g.antes(i)), moneda);
        return new RenglonGlobal(actual, antes, varia);
    }

    private static BigDecimal escala(BigDecimal v, int moneda) {
        BigDecimal r = (moneda == 1) ? v.divide(MIL, 0, RoundingMode.DOWN) : v.setScale(0, RoundingMode.DOWN);
        return r;   // los campos editados ZZZZ,ZZZ,ZZZ no tienen signo: el formateador debe decidirlo
    }
}

@Service
@RequiredArgsConstructor
class CatalogoNumDias {

    private final CatalogoEstructuraClient s080;   // L710_CONSUL_DETALLE IN ESTRUCTURA
    @Value("${p050.capsula.num-dias-default:180}") private int numDiasDefault;

    /** Catálogo 802, búsqueda 2, llaves 500 y 98, solicitado por sistema 151 programa 50. */
    int numDias() {
        return s080.consultaDetalle(802, 2, List.of(500, 98), 151, 50)
                .map(det -> det.dato(3))          // WKS-SL710-DAT(3)
                .orElse(numDiasDefault);          // MOVE 180 TO W77-NUMDIAS
    }
}

